package main

import (
	"fmt"
	"sync"
)

type Account struct {
	mu      sync.Mutex
	balance int
}

func (a *Account) Withdraw(n int) error {
	a.mu.Lock()
	defer a.mu.Unlock() // released on every return path
	if n > a.balance {
		return fmt.Errorf("insufficient funds")
	}
	a.balance -= n
	return nil
}

func main() {
	a := &Account{balance: 100}
	fmt.Println(a.Withdraw(150))
	// Output: insufficient funds
}

