import (
	"fmt"
	"sync/atomic"
)

func main() {
	// Fixing a race: atomic.AddInt64 synchronizes the increment.
	var n int64
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() { defer wg.Done(); atomic.AddInt64(&n, 1) }()
	}
	wg.Wait()
	fmt.Println(atomic.LoadInt64(&n))
	// Output: 100
}

