import "sync"

// WorkerPool runs process over jobs with exactly n workers,
// returning results aligned to the input order.
func WorkerPool(n int, jobs []int, process func(int) int) []int {
	if n < 1 {
		n = 1
	}
	results := make([]int, len(jobs)) // one slot per job
	idxCh := make(chan int)           // feeds job indices to workers
	var wg sync.WaitGroup
	for w := 0; w < n; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range idxCh {        // pull work until channel closes
				results[i] = process(jobs[i]) // disjoint index: no lock needed
			}
		}()
	}
	for i := range jobs {
		idxCh <- i
	}
	close(idxCh) // signal no more work; workers drain and exit
	wg.Wait()    // block until every worker finished
	return results
}

type SafeMap struct {
	mu sync.RWMutex
	m  map[string]int
}

func NewSafeMap() *SafeMap { return &SafeMap{m: make(map[string]int)} }

func (s *SafeMap) Get(k string) (int, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()      // shared read lock
	v, ok := s.m[k]
	return v, ok
}

func (s *SafeMap) Set(k string, v int) {
	s.mu.Lock()
	defer s.mu.Unlock()       // exclusive write lock
	s.m[k] = v
}

func (s *SafeMap) Len() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return len(s.m)
}
